// ---- edit policy here ----
const CONFIG = {
  leaseSeconds: 60,              // how long an in-flight request owns its key (keep above providerTimeoutMs)
  providerTimeoutMs: 30000,
  maxAmount: 50000,
  allowedCurrencies: ['USD', 'EUR', 'GBP', 'INR'],
  providerUrl: 'https://httpbin.org/post',   // replace with your payment provider endpoint
  allowSimulation: true          // demo only: lets a request add simulateStatus to test provider failures
};

// SHA-256 (no external modules needed)
const primes = [];
for (let n = 2; primes.length < 64; n++) if (primes.every(p => n % p)) primes.push(n);
const frac = x => Math.floor((x - Math.floor(x)) * 4294967296);
const K = primes.map(p => frac(Math.cbrt(p)));
const H0 = primes.slice(0, 8).map(p => frac(Math.sqrt(p)));
function sha256(str) {
  const bytes = unescape(encodeURIComponent(str)).split('').map(c => c.charCodeAt(0));
  const l = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(l * 8 / 4294967296), lo = (l * 8) >>> 0;
  for (let i = 3; i >= 0; i--) bytes.push((hi >>> (i * 8)) & 255);
  for (let i = 3; i >= 0; i--) bytes.push((lo >>> (i * 8)) & 255);
  const H = H0.slice();
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = ((bytes[off + 4 * i] << 24) | (bytes[off + 4 * i + 1] << 16) | (bytes[off + 4 * i + 2] << 8) | bytes[off + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

const hook = ref('Webhook - Payment Request');
const headers = hook.headers || {};
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const rawKey = String(headers['idempotency-key'] || body.idempotencyKey || '').trim();
const clientId = String(headers['x-client-id'] || body.clientId || 'default').trim();
if (!rawKey) errors.push('Missing Idempotency-Key header');
else if (!/^[A-Za-z0-9_\-:.]{8,128}$/.test(rawKey)) errors.push('Idempotency-Key must be 8-128 characters of A-Z a-z 0-9 _ - : .');
if (!/^[A-Za-z0-9_\-:.]{1,64}$/.test(clientId)) errors.push('X-Client-Id must be 1-64 characters of A-Z a-z 0-9 _ - : .');

const amount = Number(body.amount);
if (!Number.isFinite(amount) || amount <= 0) errors.push('amount must be a positive number');
else if (amount > CONFIG.maxAmount) errors.push('amount exceeds the maximum of ' + CONFIG.maxAmount);
else if (Math.abs(amount * 100 - Math.round(amount * 100)) > 1e-6) errors.push('amount supports at most 2 decimal places');

const currency = String(body.currency || '').toUpperCase();
if (!CONFIG.allowedCurrencies.includes(currency)) errors.push('currency must be one of ' + CONFIG.allowedCurrencies.join(', '));
const customerId = String(body.customerId || '').trim();
if (!customerId) errors.push('customerId is required');
const orderId = body.orderId ? String(body.orderId).trim() : '';
if (orderId && !/^[A-Za-z0-9_\-:.]{1,64}$/.test(orderId)) errors.push('orderId must be 1-64 characters of A-Z a-z 0-9 _ - : .');
const description = body.description ? String(body.description).slice(0, 200) : '';

const valid = errors.length === 0;
const amountMinor = Math.round(amount * 100);

// Canonical payload -> fingerprint: the same key with a different payload is rejected.
const canon = JSON.stringify({ customerId, amountMinor, currency, orderId: orderId || null, description: description || null });
const fingerprint = valid ? sha256(canon) : null;

let providerUrl = CONFIG.providerUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) providerUrl = 'https://httpbin.org/status/' + sim;

return [{
  json: {
    valid,
    errors,
    idemKey: valid ? clientId + ':' + rawKey : null,
    businessKey: valid && orderId ? clientId + ':' + orderId : null,
    fingerprint,
    request: { customerId, amount, amountMinor, currency, orderId: orderId || null, description: description || null },
    provider: {
      url: providerUrl,
      body: { amount: amountMinor, currency, customer: customerId, reference: orderId || null, description: description || null }
    },
    config: CONFIG
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const v = ref('Code - Validate & Fingerprint');
const row = $input.first().json || {};
const out = (route, httpStatus, body, extra = {}) => [{ json: { route, httpStatus, body, idemKey: v.idemKey || '', replayed: false, ...extra } }];

if (!v.valid) return out('invalid', 400, { error: 'invalid_request', details: v.errors });

if (row.error) {
  const em = typeof row.error === 'string' ? row.error : (row.error.message || JSON.stringify(row.error));
  if (/uq_idem_business_active|duplicate key/i.test(em)) {
    return out('duplicate', 409, {
      error: 'duplicate_transaction',
      message: 'A transaction for this orderId is already in progress or completed under a different Idempotency-Key.',
      orderId: v.request.orderId
    });
  }
  // Fail closed: if the idempotency store cannot be trusted, never call the payment provider.
  return out('store_unavailable', 503, {
    error: 'idempotency_store_unavailable',
    message: 'Idempotency could not be verified, so no payment was attempted. Retry later with the same Idempotency-Key.'
  });
}

if (row.idem_key && row.claimed === true) {
  return [{ json: { route: 'execute', idemKey: v.idemKey, attempt: Number(row.attempts), fingerprint: v.fingerprint, request: v.request, provider: v.provider, config: v.config } }];
}

if (row.idem_key) {
  if (row.fingerprint !== v.fingerprint) {
    return out('mismatch', 422, { error: 'idempotency_key_reuse', message: 'This Idempotency-Key was already used with a different request payload.' });
  }
  if (row.status === 'completed') {
    let rb = row.response_body;
    if (typeof rb === 'string') { try { rb = JSON.parse(rb); } catch (e) { rb = { raw: rb }; } }
    return [{ json: { route: 'replay', httpStatus: Number(row.response_code) || 200, body: rb, idemKey: v.idemKey, replayed: true } }];
  }
}

return out('in_progress', 409, {
  error: 'request_in_progress',
  message: 'A request with this Idempotency-Key is still being processed. Retry shortly with the same key.',
  retryAfterSeconds: 5
});

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Route Request');
const r = $input.first().json;
const statusCode = Number(r.statusCode) || 0;

let pb = r.body;
if (typeof pb === 'string') { try { pb = JSON.parse(pb); } catch (e) { pb = { raw: pb.slice(0, 300) }; } }
if (!pb || typeof pb !== 'object') pb = {};

let finalStatus, httpStatus, body, providerRef = null;

if (statusCode >= 200 && statusCode < 300) {
  // Success: store and replay this exact response for the same key.
  finalStatus = 'completed';
  httpStatus = 201;
  providerRef = pb.id || pb.transactionId || ('TXN-' + String(ctx.fingerprint).slice(0, 16).toUpperCase());
  body = {
    status: 'succeeded',
    transactionId: providerRef,
    amount: ctx.request.amount,
    currency: ctx.request.currency,
    orderId: ctx.request.orderId,
    processedAt: new Date().toISOString(),
    attempts: ctx.attempt
  };
} else if (statusCode >= 400 && statusCode < 500 && statusCode !== 408 && statusCode !== 429) {
  // Definitive rejection (declined, invalid card, ...): also final, so a retry replays it instead of re-charging.
  finalStatus = 'completed';
  httpStatus = statusCode === 402 ? 402 : 422;
  body = {
    status: 'declined',
    providerStatus: statusCode,
    message: (pb.error && pb.error.message) || pb.message || 'Rejected by the payment provider',
    orderId: ctx.request.orderId
  };
} else {
  // Timeout, network error, 429 or 5xx: outcome unknown. Release the key so the client can retry with the same
  // Idempotency-Key (the provider deduplicates, so a retry cannot double charge).
  finalStatus = 'failed';
  httpStatus = statusCode === 429 ? 429 : (statusCode ? 502 : 504);
  body = {
    status: 'failed',
    retryable: true,
    providerStatus: statusCode || null,
    message: 'The provider did not confirm the transaction. Retry with the same Idempotency-Key.',
    orderId: ctx.request.orderId
  };
}

return [{ json: { finalStatus, httpStatus, body, providerRef, providerStatus: statusCode || null, idemKey: ctx.idemKey, attempt: ctx.attempt, replayed: false } }];
